-- FAILURE-MODES-GITHUB-1 (#5532, 2026-11-03, charter pillar autonomy).
-- GitHub-derived signals are reported by PORTFOLIO-STANDARDS-1; qnfo-audit's current probe transports
-- cannot read the GitHub data directly. Each d1-query contract below verifies registry presence only.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-github-user-quota-exhausted','fm-committed-credential','fm-codeql-setup-failed','fm-no-security-policy','fm-workflow-token-default-write','fm-licence-ref-stale','fm-copilot-credits-exhausted','fm-copilot-assignment-starved'); DELETE FROM failure_modes WHERE fm_key IN ('fm-github-user-quota-exhausted','fm-committed-credential','fm-codeql-setup-failed','fm-no-security-policy','fm-workflow-token-default-write','fm-licence-ref-stale','fm-copilot-credits-exhausted','fm-copilot-assignment-starved');

INSERT OR IGNORE INTO failure_modes
  (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES
  ('fm-github-user-quota-exhausted', 'The owner''s REST core quota reached 0 from 09:37Z to 09:46Z on 2026-10-30; the steward latched rate_limited and skipped its mirror, sync and portfolio stages', 'Interactive sessions ran repository-wide REST scans under the identity the loops use for administration; GraphQL has its own bucket and stayed at 4,700 of 5,000', 'Session rule in the agent library: read GET /rate_limit first, stop below 1,500, use shallow clones, GraphQL batches and ETags; loops read with the App installation token', 'steward GET /tracker last_run.rate_limited is true in 2 of the last 6 ticks', 'fm-github-user-quota-exhausted', '2026-10-30', 5532, 'The steward tracker reports last_run.rate_limited=true in 2 of the last 6 ticks', 'The steward skips mirror, sync and portfolio stages while rate_limited is latched', 'GitHub REST operations by the owner identity and every steward stage that depends on them'),
  ('fm-committed-credential', 'Credential literals have been committed to public repositories since 2026-08', 'Secret scanning does not cover them; its enabling action covers qnfo-workers only, and no detector scans Git history', 'GITHUB-STEWARD-2 enables secret scanning and push protection; the owner rotates exposed credentials', 'Open secret-scanning alerts above 0 for any public repository (PORTFOLIO-STANDARDS-1 flag committed-credential)', 'fm-committed-credential', '2026-08-01', 5532, 'Any public repository has more than 0 open secret-scanning alerts', 'A committed credential remains present in public Git history', 'Credentials and services exposed by any public repository'),
  ('fm-codeql-setup-failed', 'CodeQL default setup failed with no later success in 19 public repositories (8 are forks)', 'Not determinable read-only (job logs expired, HTTP 410)', 'Forks: Actions and default setup off (GITHUB-STEWARD-2); other repositories: reconfigure and read the first job log', 'statusCheckRollup.state=FAILURE on an active default branch (PORTFOLIO-STANDARDS-1 flag codeql-setup-failed)', 'fm-codeql-setup-failed', '2026-10-30', 5532, 'An active default branch has statusCheckRollup.state=FAILURE', 'CodeQL setup remains failed without a later successful run', 'Code scanning coverage of the affected public repositories'),
  ('fm-no-security-policy', 'No security policy exists in any public repository although private vulnerability reporting is on', 'No security policy was ever added', 'Add organisation SECURITY.md in QNFO/.github', 'isSecurityPolicyEnabled=false (PORTFOLIO-STANDARDS-1 flag no-security-policy)', 'fm-no-security-policy', '2026-10-30', 5532, 'A public repository has isSecurityPolicyEnabled=false', 'A public repository has no published security policy', 'Security vulnerability reporting guidance across public repositories'),
  ('fm-workflow-token-default-write', 'The organisation default workflow token is write and workflows are allowed to approve pull requests', 'The defect was measured on 2026-10-17 but never added to declared state', 'GITHUB-STEWARD-2', 'GET /orgs/QNFO/actions/permissions/workflow reports write default permissions and enabled pull-request approval', 'fm-workflow-token-default-write', '2026-10-17', 5532, 'The workflow permissions endpoint reports default_workflow_permissions=write or can_approve_pull_request_reviews=true', 'Workflows receive write permissions by default and may approve pull requests', 'All QNFO organisation repositories and workflows'),
  ('fm-licence-ref-stale', 'READMEs name a licence version that the licence repository has superseded', 'v2.1 was posted without updating references', 'Open a pull request in each affected repository; PORTFOLIO-STANDARDS-1 raises the stale-license-ref flag', 'README licence lines differ from QNFO/license (PORTFOLIO-STANDARDS-1 flag stale-license-ref)', 'fm-licence-ref-stale', '2026-10-30', 5532, 'A README licence reference differs from the current QNFO/license version', 'A README points readers to a superseded licence version', 'Public repositories with stale licence references'),
  ('fm-copilot-credits-exhausted', 'Copilot answered an assigned issue with "You don''t have sufficient GitHub AI Credits to start a session" on 2026-10-31 11:32Z; sessions were starting again on 2026-11-01', 'The assignment sweep assigns work without reading the credit balance or the agent''s answer', 'The sweep reads the newest Copilot comment on an assigned issue and stops assigning while it holds that sentence, files one issue, and leaves the work to the code loop', 'An assigned issue whose newest Copilot comment contains "You don''t have sufficient GitHub AI Credits to start a session"', 'fm-copilot-credits-exhausted', '2026-10-31', 5532, 'An assigned issue has the credit-exhaustion sentence in its newest Copilot comment', 'The assignment sweep starts sessions after Copilot has reported exhausted credits', 'Copilot assignments and the issue queue awaiting those sessions'),
  ('fm-copilot-assignment-starved', 'New issues are accepted but not worked: at 10:19Z on 2026-11-01 the assignment sweep reported open_copilot_prs=12, capacity=0, deferred=161', 'The maxOpen cap of 12 is binding and the queue drains oldest-first, at most 10 per run; the hub also holds 148 open issues against the target of fewer than 100', 'Review the cap as a cost-control decision and roll up or close duplicate inflow; provide a way for human-filed priority issues to jump the queue', 'Sweep RESULT_JSON reports deferred>0 and capacity=0 for more than 24 hours', 'fm-copilot-assignment-starved', '2026-11-01', 5532, 'The sweep reports deferred>0 and capacity=0 for more than 24 hours', 'New issues remain deferred while all Copilot pull-request capacity is occupied', 'New GitHub issues awaiting assignment and remediation');

